pub fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    debug_assert_eq!(a.len(), b.len(), "Inputs must have the same length");
    debug_assert!(!a.is_empty(), "Inputs must be non-empty");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x ^ y)
        .collect()
}